    extrude(context, id + "hole", { "entities" : qSketchRegion(id + "holeSketch"), "endBound" : BoundingType.THROUGH_ALL, "oppositeDirection" : true, "operationType" : NewBodyOperationType.REMOVE, "defaultScope" : false, "booleanScope" : qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID) });
